use std::io::{Cursor,Read,Write,Seek,SeekFrom};
use zip::{ZipWriter,ZipArchive,CompressionMethod,AesMode};
use zip::write::SimpleFileOptions;
use zip::unstable::write::FileOptionsExt;
fn opt() -> SimpleFileOptions { SimpleFileOptions::default().compression_method(CompressionMethod::Stored) }
fn main() {
 for method in [CompressionMethod::Stored,CompressionMethod::Deflated,CompressionMethod::Zstd,CompressionMethod::Ppmd,CompressionMethod::Bzip2,CompressionMethod::Xz] {
  let mut w=ZipWriter::new(Cursor::new(Vec::new())); w.start_file("f",opt().compression_method(method)).unwrap(); w.write_all(b"hello").unwrap(); let mut a=ZipArchive::new(w.finish().unwrap()).unwrap(); let mut dst=ZipWriter::new(Cursor::new(Vec::new())); let r=dst.raw_copy_file(a.by_index(0).unwrap()); let mut out=Vec::new(); let r=r.and_then(|_|ZipArchive::new(dst.finish().unwrap()).unwrap().by_index(0).unwrap().read_to_end(&mut out).map_err(Into::into)); println!("raw copy {method:?} {r:?} {out:?}");
 }
 let mut w=ZipWriter::new(Cursor::new(Vec::new())); w.start_file("f",opt().with_deprecated_encryption(b"password")).unwrap(); w.write_all(b"hello").unwrap(); let mut a=ZipArchive::new(w.finish().unwrap()).unwrap(); let mut dst=ZipWriter::new(Cursor::new(Vec::new())); dst.raw_copy_file(a.by_index_raw(0).unwrap()).unwrap(); let mut b=ZipArchive::new(dst.finish().unwrap()).unwrap(); let mut out=Vec::new(); let mut f=b.by_index_decrypt(0,b"password").unwrap(); println!("raw zipcrypto encrypted={} read={:?}",f.encrypted(), f.read_to_end(&mut out));
 let mut w=ZipWriter::new(Cursor::new(Vec::new())); w.start_file("f",opt().with_aes_encryption(AesMode::Aes128,"password")).unwrap(); w.write_all(b"hello").unwrap(); let mut a=ZipArchive::new(w.finish().unwrap()).unwrap(); let mut dst=ZipWriter::new(Cursor::new(Vec::new())); dst.raw_copy_file(a.by_index_decrypt(0,b"password").unwrap()).unwrap(); let mut b=ZipArchive::new(dst.finish().unwrap()).unwrap(); let r=b.by_index_decrypt(0,b"password").map(|_|()); println!("raw AES from decrypted handle={r:?}");
 let mut w=ZipWriter::new(Cursor::new(Vec::new())); w.add_symlink("link","target",opt()).unwrap(); let mut a=ZipArchive::new(w.finish().unwrap()).unwrap(); let mut dst=ZipWriter::new(Cursor::new(Vec::new())); dst.raw_copy_file(a.by_index_raw(0).unwrap()).unwrap(); let mut b=ZipArchive::new(dst.finish().unwrap()).unwrap(); let f=b.by_index(0).unwrap(); println!("raw symlink is_symlink={} mode={:o}", f.is_symlink(), f.unix_mode().unwrap());
 let f=std::fs::OpenOptions::new().create(true).truncate(true).read(true).write(true).open("/work/tmp/sparse.zip").unwrap(); let mut f=f; f.seek(SeekFrom::Start(u32::MAX as u64+100)).unwrap(); let mut w=ZipWriter::new(f); w.start_file("f",opt()).unwrap(); w.write_all(b"hello").unwrap(); let mut a=ZipArchive::new(w.finish().unwrap()).unwrap(); let mut out=Vec::new(); println!("high offset initial={:?}",a.by_index(0).unwrap().read_to_end(&mut out)); let mut f=a.into_inner(); let mut w=ZipWriter::new_append(&mut f).unwrap(); w.start_file("g",opt()).unwrap(); w.write_all(b"world").unwrap(); w.finish().unwrap(); let mut a=ZipArchive::new(f).unwrap(); println!("high offset appended original={:?}",a.by_index(0).map(|_|()));
}
